<script setup lang="ts">
import {computed,watch,onUnmounted,ref} from 'vue';import {useRouter} from 'vue-router';import {useFeedbackSubmission} from './useFeedbackSubmission';import {useFeedbackList} from './useFeedbackList';import {useRoute} from 'vue-router';import {useApplication} from '../../application';import Icon from '../../shared/Icon.vue';const route=useRoute(),feedback=computed(()=>route.path==='/feedback'),tab=ref('全部'),q=ref(''),app=useApplication(),feedbackError=ref<string|null>(null),feedbackDialog=ref<HTMLDialogElement>(),feedbackCategory=ref('WORDING'),feedbackComment=ref(''),feedbackMeetingId=ref(typeof route.query.meetingId==='string'?route.query.meetingId:'');
const router=useRouter(),feedbackBusy=ref(false),feedbackSubmission=useFeedbackSubmission(app.feedback,()=>app.session.current.value?.actor.enterpriseId??null,app.journals);
const feedbackList=useFeedbackList(app.feedback,()=>app.session.current.value?.actor.enterpriseId??null),feedbackItems=feedbackList.items,feedbackNext=feedbackList.next,feedbackLoading=feedbackList.loading;
const feedbackStates:Record<string,string>={'待审核':'PENDING','已通过':'ACCEPTED','已驳回':'REJECTED','需要补充':'NEEDS_MORE'},visibleFeedback=computed(()=>feedbackItems.value.filter(item=>tab.value==='全部'||item.state===feedbackStates[tab.value]));
function openFeedback(){try{const restored=feedbackSubmission.open(feedbackMeetingId.value);if(restored){feedbackMeetingId.value=restored.meetingId;feedbackCategory.value=restored.category;feedbackComment.value=restored.comment;}feedbackDialog.value?.showModal();}catch(cause){feedbackError.value=cause instanceof Error?cause.message:'原反馈暂无法读取';}}
function closeFeedback(){if(!feedbackBusy.value&&!feedbackSubmission.pending.value)feedbackDialog.value?.close();}
async function loadFeedback(cursor:string|null=null){if(feedback.value)await feedbackList.load(cursor);}
async function submitFeedback(){if(feedbackBusy.value)return;feedbackBusy.value=true;try{if(!/^[0-9a-f-]{36}$/.test(feedbackMeetingId.value))throw new Error('请从具体会议进入反馈，才能绑定来源会议。');if(!feedbackSubmission.available.value)feedbackSubmission.open(feedbackMeetingId.value);await router.replace({query:{...route.query,meetingId:feedbackMeetingId.value}});await feedbackSubmission.submit({meetingId:feedbackMeetingId.value,category:feedbackCategory.value,comment:feedbackComment.value});feedbackComment.value='';feedbackError.value=null;feedbackDialog.value?.close();await loadFeedback();}catch(cause){feedbackError.value=cause instanceof Error?cause.message:'反馈结果尚未确认，请保留原请求重试。';}finally{feedbackBusy.value=false;}}
const stopFeedback=watch(()=>app.session.current.value?.actor.enterpriseId??null,who=>{feedbackList.invalidate();feedbackSubmission.dispose();feedbackComment.value='';feedbackDialog.value?.close();if(who)void loadFeedback();},{immediate:true});
onUnmounted(()=>{stopFeedback();feedbackList.invalidate();feedbackSubmission.dispose();});
</script>
<template><div class="layout"><div class="main"><header class="topbar"><RouterLink to="/meetings" class="topbar-home"><Icon name="list"/> 我的会议</RouterLink><span class="topbar-crumb">/ {{feedback?'我的语料反馈':'会议库'}}</span></header><main class="content"><div class="page-head"><div><h1 class="page-title">{{feedback?'我的语料反馈':'会议库'}}</h1><p class="page-desc">{{feedback?'仅展示本人提交的内容 · 会议内单次修改须经平台管理员审核后才会更新全局企业语料':'查找已发布会议成果，按知识库权限访问正式文档。'}}</p></div><RouterLink class="btn" to="/meetings">返回我的会议</RouterLink></div><div v-if="feedbackError||feedbackList.error.value" class="banner error" role="alert">{{feedbackError??feedbackList.error.value}}</div><div v-if="feedback" class="tabs" role="tablist" aria-label="反馈状态"><button v-for="name in ['全部','待审核','已通过','已驳回','需要补充']" :key="name" class="tab" role="tab" :class="{active:tab===name}" :aria-selected="tab===name" @click="tab=name">{{name}}</button><button class="btn sm" @click="openFeedback">提交反馈</button></div><div v-else class="filterbar"><input v-model="q" class="input" placeholder="搜索会议名称 / 纪要内容"/><select class="select" disabled><option>全部知识库</option></select><select class="select" disabled><option>全部分类</option></select></div><section class="card"><div style="overflow:auto"><table class="tbl"><thead><tr><template v-if="feedback"><th>类型</th><th>反馈内容</th><th>来源会议</th><th>状态</th></template><template v-else><th>会议名称</th><th>会议分类</th><th>参会人</th><th>会议日期</th><th>发布知识库</th><th>发布时间</th><th>操作</th></template></tr></thead><tbody v-if="feedback"><tr v-for="item in visibleFeedback" :key="item.id"><td>{{item.category}}</td><td>{{item.comment}}</td><td>{{item.meetingId}}</td><td>{{item.state}}</td></tr><tr v-if="!visibleFeedback.length"><td colspan="4" class="empty">{{feedbackLoading?'正在加载反馈…':'暂无反馈记录'}}</td></tr></tbody></table></div><div v-if="feedback" class="flex"><button v-if="feedbackNext" class="btn sm" :disabled="feedbackLoading" @click="loadFeedback(feedbackNext)">下一页反馈</button><button class="btn sm" :disabled="feedbackLoading" @click="loadFeedback()">重新读取反馈</button></div><div v-if="!feedback" class="empty"><Icon name="layers" :size="36"/><h2>暂无可读取的会议库成果</h2><p>已发布会议的真实正式文档，可从我的会议进入查看。</p></div></section><dialog ref="feedbackDialog" class="notice-dialog" @cancel.prevent="closeFeedback"><form method="dialog" @submit.prevent="submitFeedback"><h2>提交语料反馈</h2><label class="form-label">来源会议编号<input v-model="feedbackMeetingId" :readonly="feedbackBusy||feedbackSubmission.pending.value" class="input" placeholder="请输入有权访问的会议编号" required/></label><label class="form-label">反馈类型<select v-model="feedbackCategory" :disabled="feedbackBusy||feedbackSubmission.pending.value" class="select"><option value="WORDING">文字</option><option value="LABEL">标签</option><option value="ACTION_OWNER">行动负责人</option></select></label><label class="form-label">反馈内容<textarea v-model="feedbackComment" :readonly="feedbackBusy||feedbackSubmission.pending.value" maxlength="4096" class="input" required rows="4"></textarea></label><div class="flex"><button class="btn" type="button"  :disabled="feedbackBusy||feedbackSubmission.pending.value" @click="closeFeedback">取消</button><button v-if="['CONFLICT','REJECTED'].includes(feedbackSubmission.command.state.value)" class="btn" type="button" @click="feedbackSubmission.discardRejected()">放弃已拒绝的原反馈</button><button class="btn primary" type="submit" :disabled="feedbackBusy||!feedbackComment.trim()">{{feedbackSubmission.pending.value?'重试原反馈':'提交'}}</button></div></form></dialog></main></div></div></template>
